1: // Smoke test for /onboarding — verifies the two CTAs render and the
2: // paste-token flow calls acceptInvitation.
3: import { render, screen, fireEvent, waitFor } from "@testing-library/react";
4: import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
5: import { describe, expect, it, vi } from "vitest";
6: import { OnboardingRoute } from "@/routes/onboarding";
7: 
8: const acceptSpy = vi.fn();
9: vi.mock("@/features/tenants/api/hooks", () => ({
10:   useAcceptInvitationMutation: () => ({
11:     mutate: (token: string, opts?: { onSuccess?: () => void; onError?: (e: Error) => void }) => {
12:       acceptSpy(token);
13:       opts?.onSuccess?.();
14:     },
15:     isPending: false,
16:   }),
17: }));
18: 
19: vi.mock("@tanstack/react-router", async () => {
20:   const actual = await vi.importActual<object>("@tanstack/react-router");
21:   return {
22:     ...actual,
23:     useNavigate: () => () => undefined,
24:   };
25: });
26: 
27: function renderOnboarding() {
28:   return render(
29:     <QueryClientProvider client={new QueryClient()}>
30:       <OnboardingRoute />
31:     </QueryClientProvider>,
32:   );
33: }
34: 
35: describe("OnboardingRoute", () => {
36:   it("renders both CTAs", () => {
37:     renderOnboarding();
38:     expect(screen.getByRole("button", { name: /Crear empresa/i })).toBeInTheDocument();
39:     expect(screen.getByLabelText(/Código de invitación/i)).toBeInTheDocument();
40:   });
41: 
42:   it("calls acceptInvitation when a token is pasted and submitted", async () => {
43:     renderOnboarding();
44:     fireEvent.change(screen.getByLabelText(/Código de invitación/i), {
45:       target: { value: "abc.def.ghi" },
46:     });
47:     fireEvent.click(screen.getByRole("button", { name: /Unirme/i }));
48:     await waitFor(() => expect(acceptSpy).toHaveBeenCalledWith("abc.def.ghi"));
49:   });
50: });
